## Why This Is Asked
This question probes real-time blind source separation under changing source counts and practical latency constraints in a busy open-plan office—a common production scenario.

## Key Concepts
- Online whitening with forgetting factors to handle nonstationary noise
- MDL-based dynamic model-order estimation for adaptive source-count tracking
- Per-bin ICA with natural gradient updates and adaptive demixer sizing (6×K per frequency bin)
- Cross-bin permutation resolution via envelope coherence
- On-device evaluation using SDR/SIR metrics with ground-truth sources

## Code Example
```javascript
class AdaptiveConvolutiveICA {
  constructor(nMics, frameSize, hopSize, maxSources = 5) {
    this.nMics = nMics;
    this.frameSize = frameSize;
    this.hopSize = hopSize;
    this.maxSources = maxSources;
    this.binCount = frameSize / 2 + 1;
    this.demixers = [];  // Per-bin demixing matrices
    this.sourceCount = 1;
    this.forgettingFactor = 0.999;
    this.whiteningMatrix = this.computeInitialWhitening();
  }

  estimateSourceCount(covarianceMatrix) {
    const eigenvalues = this.computeEigenvalues(covarianceMatrix);
    const mdlScores = eigenvalues.map((_, k) =>
      this.computeMDLScore(eigenvalues, k + 1)
    );
    return mdlScores.indexOf(Math.min(...mdlScores)) + 1;
  }

  computeMDLScore(eigenvalues, k) {
    const n = eigenvalues.length;
    const lambda = eigenvalues.slice(0, k);
    const rho = eigenvalues.slice(k);
    const L = -k * n / 2 * Math.log(lambda.reduce((a, b) => a * b, 1) ** (1/n));
    const P = -rho.length * n / 2 * Math.log(rho.reduce((a, b) => a * b, 1) ** (1/n));
    const penalty = k / 2 * Math.log(n) * n;
    return -L - P + penalty;
  }

  updateDemixer(binIdx, gradient) {
    const W = this.demixers[binIdx];
    const mu = 0.01 / (1 + 0.001 * this.iteration);
    const I = Matrix.eye(W.rows);
    const gradOrtho = W - W.T.inv().T;  // Natural gradient approximation
    this.demixers[binIdx] = W + mu * gradOrtho;
  }

  resolvePermutation() {
    const envelopes = this.demixers.map(W =>
      this.computeEnvelope(W * this.mixings[W.rows])
    );
    const correlations = this.computeCorrelationMatrix(envelopes);
    return this.hungarianAssignment(correlations);
  }

  computeEnvelope(signal) {
    return signal.map(x => Math.abs(x) + 0.001);
  }

  processFrame(mixture) {
    const spectrum = this.stft(mixture);
    const whitened = spectrum.map(bin => this.whiteningMatrix.dot(bin));

    // Update source count estimate every N frames
    if (this.frameCount % 100 === 0) {
      const cov = this.estimateCovariance(whitened);
      this.sourceCount = Math.min(
        this.estimateSourceCount(cov),
        this.maxSources
      );
      this.resizeDemixers();
    }

    this.demixers = whitened.map((bin, i) => {
      const gradient = this.computeGradient(bin, this.demixers[i]);
      return this.updateDemixer(i, gradient);
    });

    const separation = this.demixers.map(W => W.dot(spectrum));
    const perm = this.resolvePermutation();
    return this.permuteAndISTFT(separation, perm);
  }

  resizeDemixers() {
    this.demixers = this.demixers.map(W => {
      if (W.cols < this.sourceCount) {
        return Matrix.concat(W, Matrix.rand(W.rows, this.sourceCount - W.cols));
      }
      return W.slice(0, W.rows, 0, this.sourceCount);
    });
  }
}

// On-device evaluation with ground-truth sources
function evaluateSeparation(estimated, groundTruth) {
  const SDR = computeSDR(estimated, groundTruth);
  const SIR = computeSIR(estimated, groundTruth);
  const SAR = computeSAR(estimated, groundTruth);
  return { SDR, SIR, SAR };
}
```

## Why This Is Asked

This question evaluates understanding of real-time blind source separation in challenging acoustic environments. Outdoor drone applications with moving sensors and wind noise test knowledge of online adaptation, computational efficiency under strict latency constraints, and robust source-tracking at the edge.

## Key Concepts

- **Online Convolutive ICA**: Real-time demixing using forgetting factors for adaptation, requiring careful balance between tracking speed and stability
- **Per-Bin ICA vs Joint Diagonalization**: Per-bin ICA offers lower complexity and faster convergence but risks cross-bin permutation ambiguity; joint diagonalization enforces consistent demixing matrices across bins at higher computational cost
- **Cross-Bin Permutation**: Resolved using inter-channel phase differences (IPD), amplitude envelope correlation across bins, or frequency-wise continuity scoring
- **Dynamic Source Count**: Detected via eigenvalue analysis of the spatial covariance matrix, monitoring eigenvalue gaps to distinguish active sources from noise
- **On-Device Evaluation**: Synthesized ground-truth using pre-recorded bird calls convolved with measured acoustic transfer functions and synthetic wind profiles, evaluated with SDR (Signal-to-Distortion Ratio) and SIR (Signal-to-Interference Ratio)

## Code Example

```javascript
class OnlineConvolutiveICA {
  constructor(numMics = 14, numSources = 3, windowSize = 1024, hopSize = 512) {
    this.numMics = numMics;
    this.numSources = numSources;
    this.windowSize = windowSize;
    this.hopSize = hopSize;
    this.forgettingFactor = 0.995;
    this.W = new Array(numSources).fill(null).map(() => 
      new Array(numMics).fill(null).map(() => 
        new ComplexArray(numMics)
      )
    );
    this.sourceCount = 0;
    this.permutationCache = new Map();
  }

  processFrame(x) {
    const X = stft(x, this.windowSize, this.hopSize);
    const numBins = X.length;
    const separated = new Array(numBins);

    for (let k = 0; k < numBins; k++) {
      const Xk = X[k];
      const Wk = this.initializeDemixerIfNeeded(k);

      const Yk = this.perBinICA(Xk, Wk);
      separated[k] = Yk;
      this.updateDemixer(Xk, Yk, k);
    }

    this.resolvePermutation(separated);
    this.detectSourceCount(X);

    return istft(separated, this.windowSize, this.hopSize);
  }

  perBinICA(Xk, Wk) {
    const whitened = this.whiten(Xk);
    const Y = matMul(Wk, whitened);
    return this.applyNonlinearity(Y);
  }

  resolvePermutation(separated) {
    for (let k = 1; k < separated.length; k++) {
      const score = this.computeEnvelopeCorrelation(
        separated[k-1], 
        separated[k]
      );
      if (score > 0.7) {
        this.alignPermutation(separated[k-1], separated[k]);
      }
    }
  }

  detectSourceCount(X) {
    const cov = this.computeSpatialCovariance(X);
    const eigenvalues = this.eigenDecompose(cov);
    const gaps = this.computeEigenvalueGaps(eigenvalues);
    this.sourceCount = this.estimateSourceCount(gaps);
  }

  computeMetrics(separated, groundTruth) {
    return {
      SDR: this.signalToDistortionRatio(separated, groundTruth),
      SIR: this.signalToInterferenceRatio(separated, groundTruth)
    };
  }
}
```

